const PRINTER_HOST = '192.168.1.20'; // <-- EDIT: your printer's IP
const PRINTER_PORT = 9100;           // <-- EDIT: 9100 is standard raw/JetDirect printing

return new Promise((resolve) => {
    let settled = false;
    const finish = (statusCode, payload) => {
        if (settled) return;
        settled = true;
        msg.statusCode = statusCode;
        msg.headers = { 'Access-Control-Allow-Origin': '*' };
        msg.payload = payload;
        resolve(msg);
    };

    const socket = net.connect({ host: PRINTER_HOST, port: PRINTER_PORT }, () => {
        socket.end(msg.payload);
    });
    socket.setTimeout(8000, () => socket.destroy(new Error('Timed out talking to the printer')));
    socket.on('close', () => finish(200, 'printed'));
    socket.on('error', (err) => {
        finish(502, 'Could not reach the printer at ' + PRINTER_HOST + ':' + PRINTER_PORT + ': ' + err.message);
    });
});
